-- Fixture for the PostgreSQL introspection tests. The schemas app and
-- billing are introspected, in that order; the expected result is in
-- postgres_schema.golden. Each table exercises the cases named above it.

CREATE SCHEMA app;
CREATE SCHEMA billing;
CREATE SCHEMA archive; -- never introspected

CREATE TYPE app.user_role AS ENUM ('admin', 'member', 'guest');
CREATE TYPE billing.currency AS ENUM ('EUR', 'USD');

-- A NOT NULL domain over a length-limited type, and a domain over a domain
-- that carries a default.
CREATE DOMAIN app.email AS varchar(254) NOT NULL;
CREATE DOMAIN app.short_code AS text;
CREATE DOMAIN app.code AS app.short_code DEFAULT 'none';

-- Identity by default, every column kind, an enum, domains, defaults.
CREATE TABLE app.users (
  id            bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  email         app.email,
  name          varchar(100) NOT NULL DEFAULT '',
  role          app.user_role NOT NULL DEFAULT 'member',
  is_active     boolean NOT NULL DEFAULT true,
  password_hash text NOT NULL,
  balance       numeric(10,2),
  rating        real,
  score         double precision,
  avatar        bytea,
  settings      jsonb,
  legacy        json,
  external_id   uuid NOT NULL DEFAULT gen_random_uuid(),
  country       char(2),
  nickname      varchar,
  birthday      date,
  wake_time     time,
  created_at    timestamptz NOT NULL DEFAULT now(),
  updated_at    timestamp,
  tags          text[],
  last_ip       inet,
  session_ttl   interval,
  referral      app.code
);

-- serial, a foreign key with an implied parent key, a self-reference, a
-- stored generated column, identity always. The CHECK ... IN list is not an
-- enum in PostgreSQL: only real enum types are.
CREATE TABLE app.posts (
  id          serial PRIMARY KEY,
  author_id   bigint NOT NULL REFERENCES app.users (id) ON DELETE CASCADE,
  reviewer_id bigint REFERENCES app.users ON DELETE SET NULL ON UPDATE CASCADE,
  parent_id   integer REFERENCES app.posts (id) ON DELETE RESTRICT,
  title       text NOT NULL,
  body        text,
  status      text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'published')),
  word_count  integer GENERATED ALWAYS AS (length(body)) STORED,
  revision    integer GENERATED ALWAYS AS IDENTITY
);

-- Text primary key.
CREATE TABLE app.tags (
  code  text PRIMARY KEY,
  label text NOT NULL
);

-- Composite primary key whose order differs from the column order.
CREATE TABLE app.post_tags (
  post_id  integer NOT NULL REFERENCES app.posts (id) ON DELETE CASCADE,
  tag_code text NOT NULL REFERENCES app.tags (code) ON DELETE RESTRICT ON UPDATE CASCADE,
  added_at timestamptz,
  PRIMARY KEY (tag_code, post_id)
);

-- Identity always as the key; composite foreign key with explicit parent
-- columns, in an order different from the parent's key.
CREATE TABLE app.tag_notes (
  id       bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  post_id  integer NOT NULL,
  tag_code text NOT NULL,
  note     text,
  FOREIGN KEY (post_id, tag_code) REFERENCES app.post_tags (post_id, tag_code) ON DELETE CASCADE
);

-- No primary key, and a composite foreign key with an implied parent key.
CREATE TABLE app.tag_votes (
  voter_id bigint NOT NULL REFERENCES app.users,
  tag_code text NOT NULL,
  post_id  integer NOT NULL,
  FOREIGN KEY (tag_code, post_id) REFERENCES app.post_tags
);

-- A partitioned table is one table; its partitions are not listed. Its
-- foreign key is copied to each partition and must be reported once.
CREATE TABLE app.events (
  id          bigint GENERATED BY DEFAULT AS IDENTITY,
  happened_at timestamptz NOT NULL,
  kind        text NOT NULL,
  user_id     bigint REFERENCES app.users (id) ON DELETE SET NULL,
  PRIMARY KEY (id, happened_at)
) PARTITION BY RANGE (happened_at);
CREATE TABLE app.events_2024 PARTITION OF app.events FOR VALUES FROM ('2024-01-01') TO ('2025-01-01');
CREATE TABLE app.events_2025 PARTITION OF app.events FOR VALUES FROM ('2025-01-01') TO ('2026-01-01');

-- A foreign key that references a partitioned table is likewise copied per
-- partition and must be reported once.
CREATE TABLE app.event_notes (
  event_id    bigint NOT NULL,
  happened_at timestamptz NOT NULL,
  note        text,
  FOREIGN KEY (event_id, happened_at) REFERENCES app.events (id, happened_at)
);

-- A table without columns.
CREATE TABLE app.empty ();

CREATE TABLE archive.invoices (id bigint PRIMARY KEY);

-- Same name as app.users; a foreign key that crosses schemas.
CREATE TABLE billing.users (
  user_id    bigint PRIMARY KEY REFERENCES app.users (id) ON DELETE CASCADE,
  currency   billing.currency NOT NULL DEFAULT 'EUR',
  vat_number text
);

-- bigserial; a foreign key to a table outside the introspected schemas.
CREATE TABLE billing.invoices (
  id          bigserial PRIMARY KEY,
  user_id     bigint NOT NULL REFERENCES billing.users (user_id),
  archived_as bigint REFERENCES archive.invoices (id) ON DELETE SET DEFAULT,
  total       numeric NOT NULL,
  issued_on   date NOT NULL DEFAULT CURRENT_DATE
);

-- Everything below must be ignored: tables in schemas that were not asked
-- for, indexes, views and materialized views.
CREATE TABLE public.outside (id integer PRIMARY KEY);
CREATE INDEX posts_author ON app.posts (author_id);
CREATE VIEW app.active_users AS SELECT id, email FROM app.users WHERE is_active;
CREATE MATERIALIZED VIEW app.user_counts AS SELECT role, count(*) AS n FROM app.users GROUP BY role;
